async function triggerCameraCapture(){const seconds=Number($('cameraTimer')?.value||state.scanOptions.timer||0);if(seconds<=0)return captureCamera(false);for(let n=seconds;n>0;n--){$('qualityHud').textContent=`Capturing in ${n}…`;await new Promise(r=>setTimeout(r,1000))}await captureCamera(false)}
function applyFrameGuide(v){const e=$('edgeGuide');e.dataset.guide=v==='auto'?(state.cameraMode==='id'?'id':state.cameraMode==='book'?'a4':'auto'):v}
async function applyCameraZoom(){try{const tr=state.cameraStream?.getVideoTracks?.()[0],v=Number($('cameraZoom').value);$('cameraZoomValue').textContent=v.toFixed(1)+'×';if(tr?.applyConstraints)await tr.applyConstraints({advanced:[{zoom:v}]})}catch{}}
