function modeHint(m){return({document:'Align document inside the frame',id:'Fit the card inside the frame',book:'Match the book gutter to the yellow line',signature:'Use dark ink on plain white paper',ocr:'Keep text sharp and evenly lit',qr:'Center QR / barcode',photo:'Natural photo capture'})[m]||'Ready'}
function liveCameraAvailable(){const protocol=String(location.protocol||'').toLowerCase();const host=String(location.hostname||'').toLowerCase();const trustedProtocol=protocol==='https:'||(protocol==='http:'&&(host==='localhost'||host==='127.0.0.1'||host==='[::1]'));return trustedProtocol&&window.isSecureContext===true&&!!navigator.mediaDevices?.getUserMedia}
function showCameraPermissionPanel(message='Camera access is unavailable in this browser session.'){const p=$('cameraPermissionPanel');if(!p)return;$('cameraPermissionMessage').textContent=message;p.hidden=false}
