function closeCamera(){stopFrameMonitor();if(state.cameraStream){state.cameraStream.getTracks().forEach(t=>t.stop());state.cameraStream=null}$('cameraOverlay').hidden=true}
async function toggleTorch(){try{const tr=state.cameraStream?.getVideoTracks?.()[0],cap=tr?.getCapabilities?.();if(cap?.torch){state.torch=!state.torch;await tr.applyConstraints({advanced:[{torch:state.torch}]});$('torchBtn').style.color=state.torch?'#ffe566':''}else toast('Torch control is not supported by this phone/browser.')}catch(e){toast(e.message,'error')}}
function updateAutoCaptureLabel(){$('autoCaptureLabel').textContent=getSetting('autoCaptureSetting',false)?'AUTO • capture when stable':'Manual capture'}
async function toggleLevel(){const guide=$('levelGuide');guide.hidden=!guide.hidden;if(guide.hidden)return;try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'){const r=await DeviceOrientationEvent.requestPermission();if(r!=='granted')return toast('Motion permission is required for the spirit level.','error')}}catch{}if(!state.levelListener){state.levelListener=e=>{if(guide.hidden)return;const gamma=Number(e.gamma||0),clamped=Math.max(-30,Math.min(30,gamma));const bar=guide.querySelector('i');bar.style.transform=`translateX(-50%) rotate(${clamped}deg)`;bar.style.background=Math.abs(gamma)<2?'#54dea5':'#ffe16a'};window.addEventListener('deviceorientation',state.levelListener,true)}}
