function scheduleFilterPreviews(delay=120){clearTimeout(filterPreviewTimer);const gen=++filterPreviewGeneration;filterPreviewTimer=setTimeout(()=>renderFilterPreviews(gen),delay)}
async function renderFilterPreviews(gen=filterPreviewGeneration){const p=state.editDraft;if(!p||!p.src)return;try{for(const b of $$('#filterStrip .filter-button')){if(gen!==filterPreviewGeneration)return;const c=b.querySelector('canvas.filter-swatch');if(!c)continue;const pp={...p,filter:b.dataset.filter,signature:null,adjust:{...(p.adjust||{}),sharpness:Math.min(35,Number(p.adjust?.sharpness||0))}},pc=await processedCanvas(pp,true,false),maxW=150,maxH=108,sc=Math.min(maxW/pc.width,maxH/pc.height);c.width=maxW;c.height=maxH;const x=c.getContext('2d');x.fillStyle='#eef3f4';x.fillRect(0,0,maxW,maxH);const w=pc.width*sc,h=pc.height*sc;x.drawImage(pc,(maxW-w)/2,(maxH-h)/2,w,h)}}catch(e){console.warn('Filter preview rendering failed',e)}}

