function resetEditDraft(){const original=state.builder.pages.find(p=>p.id===state.editingPage);state.editDraft=structuredClone(original);state.editDraft.quad=normaliseQuad(state.editDraft.quad||cropToQuad(state.editDraft.crop||{}));state.editDraft.filter='original';state.editDraft.filterIntensity=70;state.editDraft.crop={left:0,right:0,top:0,bottom:0,confidence:0};state.editDraft.fineRotation=0;state.editDraft.edgeSensitivity=1;state.editDraft.autoTrim=true;state.editDraft.adjust={brightness:0,contrast:0,sharpness:20,clarity:0,saturation:0,warmth:0,highlights:0,shadows:0};delete state.editDraft.signature;syncEditor();drawEditPreview()}
async function openPageEditor(id,newCapture=false){const p=state.builder?.pages.find(x=>x.id===id);if(!p)return;state.editingPage=id;state.editDraft=structuredClone(p);state.editDraft.quad=normaliseQuad(state.editDraft.quad||cropToQuad(state.editDraft.crop||{}));if(quadIsFull(state.editDraft.quad)){setTimeout(()=>detectCurrentCrop(),120)}$('scanEditorTitle').textContent=`${newCapture?'Review new page':'Edit page'} • ${state.builder.pages.indexOf(p)+1}`;const q=p.quality||{score:0,label:'Unknown',issues:[]},m=p.metrics||{},banner=$('scanQualityBanner');banner.className='scan-quality-banner '+(q.score>=75?'good':q.score>=55?'warn':'bad');banner.innerHTML=`<b>${q.label} • ${q.score}/100</b> — sharpness ${Math.round(m.sharpness||0)}, brightness ${Math.round(m.brightness||0)}, contrast ${Math.round(m.contrast||0)}, ${(m.megapixels||0).toFixed(1)} MP.${q.issues?.length?' Detected: '+q.issues.join(', ')+'.':''}${q.retakeRecommended?' <b>Retake recommended if text is not readable.</b>':''}`;syncEditor();openDialog('scanEditorDialog');await drawEditPreview()}
