async function savePassportLibrary(){if(!state.passport.src)return toast('Select a photo first.','error');const im=await loadImage(state.passport.src),c=document.createElement('canvas'),max=800,sc=Math.min(1,max/Math.max(im.naturalWidth,im.naturalHeight));c.width=Math.max(1,Math.round(im.naturalWidth*sc));c.height=Math.max(1,Math.round(im.naturalHeight*sc));c.getContext('2d').drawImage(im,0,0,c.width,c.height);const raw=c.toDataURL('image/jpeg',.82),preview=(await buildPassportPhotoCanvas(360)).toDataURL('image/jpeg',.88),name=$('passportStoreName').value.trim()||'Passport Photo';state.savedPassportPhotos.push({id:uid('photo'),name,raw,preview,settings:{...state.passport,src:undefined},size:state.idSize||ID_SIZES[0],created:Date.now()});persistPassportPhotos();renderSavedPassportPhotos();updateDrawerStats();toast('Passport photo saved locally for future use.','success')}
function renderSavedPassportPhotos(){const g=$('savedPassportGrid');if(!g)return;g.innerHTML='';if(!state.savedPassportPhotos.length){g.innerHTML='<p class="muted">No saved passport photos yet.</p>';return}state.savedPassportPhotos.slice().reverse().forEach(p=>{const c=document.createElement('div');c.className='saved-passport-card';c.innerHTML=`<div class="saved-passport-preview" style="background-image:url('${p.preview||p.raw}')"></div><b>${escapeHtml(p.name)}</b><div class="mini-actions"><button data-use>Edit</button><button data-delete>Delete</button></div>`;c.querySelector('[data-use]').onclick=async()=>{state.passport={...state.passport,...p.settings,src:p.raw};state.idSize=p.size||ID_SIZES[0];$('passportStoreName').value=p.name;syncPassportControls();renderDressOptions();fillPassportSizeSelect();openDialog('passportPhotoDialog');renderPassportPreview()};c.querySelector('[data-delete]').onclick=()=>{if(confirm('Delete this stored photo?')){state.savedPassportPhotos=state.savedPassportPhotos.filter(x=>x.id!==p.id);persistPassportPhotos();renderSavedPassportPhotos();updateDrawerStats()}};g.appendChild(c)})}

// Viewer & signature
async function openViewer(file,kind=C.guessFileKind(file.name,file.type)){try{if(state.viewerUrl){URL.revokeObjectURL(state.viewerUrl);state.viewerUrl=null}$('viewerTitle').textContent=file.name;$('viewerBody').innerHTML='<p class="muted">Opening preview…</p>';openDialog('viewerDialog');const body=$('viewerBody');if(kind==='pdf'){const pages=await T.renderPdf(file,1.35);body.innerHTML='';pages.forEach(c=>{c.className='pdf-page-canvas';body.appendChild(c)})}else if(kind==='image'){const u=URL.createObjectURL(file);state.viewerUrl=u;body.innerHTML=`<img class="image-view" src="${u}">`}else if(kind==='word'){await L.ensure(['mammoth']);const r=await mammoth.convertToHtml({arrayBuffer:await file.arrayBuffer()});body.innerHTML=`<article class="word-view">${r.value}</article>`}else if(kind==='excel'){await L.ensure(['xlsx']);const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});body.innerHTML='<div class="excel-view">'+wb.SheetNames.map(n=>`<h3>${escapeHtml(n)}</h3>${XLSX.utils.sheet_to_html(wb.Sheets[n])}`).join('')+'</div>'}else if(kind==='text'){body.innerHTML=`<pre class="text-view">${escapeHtml(await file.text())}</pre>`}else if(kind==='zip'||kind==='archive'){const rows=await T.archiveList(file);body.innerHTML=`<div class="archive-list">${rows.map(r=>`<div class="archive-row"><span>${r.dir?'📁':'📄'} ${escapeHtml(r.name)}</span><small>${r.size==null?'':formatBytes(r.size)}</small></div>`).join('')}</div>`}else body.innerHTML='<p>Preview is not available for this file type.</p>'}catch(e){toast(e.message,'error');$('viewerBody').innerHTML=`<p class="muted">${escapeHtml(e.message)}</p>`}}
function formatBytes(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'}
function bindSignature(){$('importSignatureBtn').onclick=()=>$('signatureImportInput').click();$('signatureImportInput').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;const im=await loadImage(await fileDataUrl(f)),c=$('signatureCanvas'),x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);const r=C.computeFit(im.naturalWidth,im.naturalHeight,c.width,c.height,20);x.drawImage(im,r.x,r.y,r.w,r.h);toast('Signature imported. Adjust darken, ink or opacity if required.','success')};$('clearSignatureBtn').onclick=clearSignature;$('flipSignatureBtn').onclick=()=>{state.signatureFlip=!state.signatureFlip;$('flipSignatureBtn').classList.toggle('active',state.signatureFlip);toast(state.signatureFlip?'Signature will be flipped horizontally.':'Signature flip removed.')};$('signatureDarken').oninput=e=>$('signatureDarkenVal').textContent=e.target.value+'%';$('signatureOpacity').oninput=e=>$('signatureOpacityVal').textContent=e.target.value+'%';$('saveSignatureBtn').onclick=()=>{const data=processedSignatureData();state.signatureData=data;if($('storeSignatureCheck').checked){const name=$('signatureName').value.trim()||'Signature';state.savedSignatures.push({id:uid('sig'),name,data,created:Date.now()});persistSignatures();renderSignatureLibrary();updateDrawerStats();toast('Signature saved to your local library.','success')}closeDialog('signatureDialog');toast('Signature ready to use.','success')}}
function renderSignatureLibrary(){const g=$('savedSignatureGrid');if(!g)return;g.innerHTML='';if(!state.savedSignatures.length){g.innerHTML='<p class="muted">No saved signatures yet.</p>';return}state.savedSignatures.slice().reverse().forEach(s=>{const c=document.createElement('div');c.className='saved-signature-card';c.innerHTML=`<div class="saved-signature-preview" style="background-image:url('${s.data}')"></div><b>${escapeHtml(s.name)}</b><div class="mini-actions"><button data-use>Use</button><button data-delete>Delete</button></div>`;c.querySelector('[data-use]').onclick=()=>{state.signatureData=s.data;drawSignatureDataToCanvas(s.data);$('signatureName').value=s.name;toast('Saved signature loaded.','success')};c.querySelector('[data-delete]').onclick=()=>{if(confirm('Delete this saved signature?')){state.savedSignatures=state.savedSignatures.filter(x=>x.id!==s.id);persistSignatures();renderSignatureLibrary();updateDrawerStats()}};g.appendChild(c)})}
async function drawSignatureDataToCanvas(data){const im=await loadImage(data),c=$('signatureCanvas'),x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);const r=C.computeFit(im.naturalWidth,im.naturalHeight,c.width,c.height,18);x.drawImage(im,r.x,r.y,r.w,r.h)}
function openSignature(showLibrary=false){clearSignature();state.signatureFlip=false;$('flipSignatureBtn').classList.remove('active');$('signatureDarken').value=115;$('signatureDarkenVal').textContent='115%';$('signatureOpacity').value=100;$('signatureOpacityVal').textContent='100%';$('storeSignatureCheck').checked=true;renderSignatureLibrary();openDialog('signatureDialog');const c=$('signatureCanvas'),x=c.getContext('2d');x.lineWidth=5;x.lineCap='round';let down=false,last=null;const pos=e=>{const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}};c.onpointerdown=e=>{down=true;last=pos(e);c.setPointerCapture?.(e.pointerId)};c.onpointermove=e=>{if(!down)return;const p=pos(e);x.strokeStyle=$('signatureColor').value||'#123642';x.beginPath();x.moveTo(last.x,last.y);x.lineTo(p.x,p.y);x.stroke();last=p};c.onpointerup=c.onpointercancel=()=>down=false}
function processedSignatureData(){const src=$('signatureCanvas'),w=src.width,h=src.height,input=src.getContext('2d').getImageData(0,0,w,h),out=document.createElement('canvas');out.width=w;out.height=h;const ox=out.getContext('2d'),img=ox.createImageData(w,h),d=input.data,o=img.data,hex=($('signatureColor').value||'#123642').replace('#',''),r=parseInt(hex.slice(0,2),16)||18,g=parseInt(hex.slice(2,4),16)||54,b=parseInt(hex.slice(4,6),16)||66,darken=Number($('signatureDarken').value||115)/100,opacity=Number($('signatureOpacity').value||100)/100;for(let i=0;i<d.length;i+=4){const lum=.299*d[i]+.587*d[i+1]+.114*d[i+2],ink=C.clamp((255-lum)/190*darken,0,1);o[i]=r;o[i+1]=g;o[i+2]=b;o[i+3]=Math.round(255*ink*opacity)}ox.putImageData(img,0,0);if(!state.signatureFlip)return out.toDataURL('image/png');const flipped=document.createElement('canvas');flipped.width=w;flipped.height=h;const fx=flipped.getContext('2d');fx.translate(w,0);fx.scale(-1,1);fx.drawImage(out,0,0);return flipped.toDataURL('image/png')}
function clearSignature(){const c=$('signatureCanvas'),x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height)}

function bindGlobalDialogs(){$$('[data-close-dialog]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.closeDialog));$$('.bottom-sheet').forEach(s=>s.addEventListener('click',e=>{if(e.target===s)s.hidden=true}));$$('#settingsPanel input,#settingsPanel select').forEach(e=>e.onchange=()=>{if(e.id==='defaultQualitySetting'&&e.value==='custom'){const n=Number(prompt('Custom longest-side capture pixels (640–4096)',state.settings.customLongEdge||2200));if(n>=640&&n<=4096)state.settings.customLongEdge=Math.round(n);else e.value='high'}saveSettings()})}

async function runSelfTest(){try{const results=[];results.push(Object.keys(PROFILES).length>=24);results.push(!!$('navDrawer')&&!!$('directCropOverlay')&&!!$('passportPhotoDialog')&&!!$('idScanOptions'));results.push(DRESS_OPTIONS.men.length>=6&&DRESS_OPTIONS.women.length>=6);results.push(FILTERS.length>=40);results.push(C.parsePageRange('1-3,5',6).join(',')==='0,1,2,4');results.push(C.guessFileKind('x.xlsx')==='excel');const q=C.classifyQuality({sharpness:280,brightness:145,contrast:50,megapixels:2.4});results.push(q.score>=65);const c=document.createElement('canvas');c.width=600;c.height=850;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle='#111';x.font='32px Arial';x.fillText('ATRANGI SCANNER V3',55,110);const src=c.toDataURL('image/jpeg',.92);state.builder={id:'self',name:'Self Test',kind:'scan',profile:'document',mode:'document',pages:[{id:'p1',name:'test',src,width:600,height:850,rotation:0,filter:'magic',filterIntensity:70,crop:{left:0,right:0,top:0,bottom:0},adjust:{brightness:0,contrast:0,sharpness:20},metrics:{sharpness:280,brightness:145,contrast:50,megapixels:.5},quality:q,ocrText:'',accepted:true}],completed:false,updated:Date.now()};const pc=await processedCanvas(state.builder.pages[0],true);results.push(pc.width>300&&pc.height>400);renderBuilder();results.push($('builderPages').children.length===1);document.body.dataset.selfTest=results.every(Boolean)?'PASS':'FAIL';toast(`Self-test ${document.body.dataset.selfTest}: ${results.filter(Boolean).length}/${results.length}`,'success')}catch(e){document.body.dataset.selfTest='FAIL:'+e.message;toast('Self-test failed: '+e.message,'error')}}

